import{_ as o,l as r,o as e,c as d,v as l,p as n,x as t,d as s,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"多模态嵌入","description":"","frontmatter":{"title":"多模态嵌入","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/multimodal-embeddings.md","filePath":"llm/multimodal-embeddings.md","lastUpdated":1789023840000}'),A={name:"llm/multimodal-embeddings.md"};function E(h,a,_,c,B,u){const i=r("Mermaid");return e(),d("div",null,[a[1]||(a[1]=l('<h1 id="多模态嵌入" tabindex="-1">多模态嵌入 <a class="header-anchor" href="#多模态嵌入" aria-label="Permalink to &quot;多模态嵌入&quot;">​</a></h1><div class="epigraph"><p>图与文进同一余弦空间，零样本就能用句子当分类器。那是双塔检索空间，不是对话 VLM 的早融合。</p><footer>—— Radford 等 CLIP；后续 ImageBind / SigLIP 把模态接口拓宽</footer></div><p><a href="/llm/long-doc-embedding">上一课</a>把文本长度钉住。检索还要图、有时要音。主干 <a href="/llm/clip">CLIP</a> 已写图文对比；<a href="/llm/early-late-fusion">早融合</a> 已警告不要把双塔叫成 LLaVA。本课在补层收成「多模态嵌入」：可预计算、可 ANN 的跨模态向量。单元到此结束。下一单元 RAG 工程默认：检索器可以是文本、图文或混合，阅读器仍是生成器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CLIP 双塔：图 \\(z_i\\) 与文 \\(w_j\\) 只在 InfoNCE 见面，推理时任一侧可先算后存。ImageBind 一类把更多模态绑到同一锚空间。SigLIP 把 softmax 对比换成 sigmoid，利于超大批。这些都是<strong>晚融合度量空间</strong>，服务检索与开放词汇分类。它们不绑定「图中第三列」——那要 VLM 早融合，本课程后一课才回到生成式多模态。</p><p>失败模式：标题偏物体名词，空间关系与细字弱；图文对噪声造成假正例。与文本难负例课同构，应用难负图文对。</p><p><span class="marginnote">把 CLIP 向量送进 LLM 当单 token，是连接器选择，不是嵌入检索。检索用的是余弦邻居，对话用的是序列绑定。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>索引：对图库算 \\(z_i\\) 存 ANN；查询可以是文本 \\(w\\) 或另一张图。多模态 RAG：检索到的是图或图文块，再交给能读图的生成器，而不是把 \\(z_i\\) 当文字拼进提示。评测：图文召回、零样本分类、与文本 MTEB 分列。不要用 ImageNet 准确率签发检索质量。</p>',9)),(e(),n(p,null,{default:t(()=>[m(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22%E5%9B%BE%E5%83%8F%E5%A1%94%22%5D%20--%3E%20S%5B%22%E5%85%B1%E4%BA%AB%E5%BA%A6%E9%87%8F%E7%A9%BA%E9%97%B4%22%5D%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%E5%A1%94%22%5D%20--%3E%20S%0A%20%20S%20--%3E%20ANN%5B%22ANN%20%E6%A3%80%E7%B4%A2%22%5D%0A%20%20ANN%20--%3E%20RAG%5B%22%E5%8F%AF%E9%80%89%EF%BC%9A%E4%BA%A4%E7%BB%99%E8%AF%BB%E5%9B%BE%E7%94%9F%E6%88%90%E5%99%A8%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>对比损失只约束全局向量近邻，不约束 patch 与词对齐。因此多模态嵌入擅长「找与这句话相近的图」，不擅长「这句话里的词对准哪个框」。定位是后一课程 grounding 的事。温度与批大小同 InfoNCE 课；跨模态假负例（同一物体不同角度被当负）同样会撕开流形。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>音频/视频嵌入还要时序池化，不能把整段波形平均成 CLIP 式全局向量就声称可检索。下一课查询改写：无论模态，用户的问题往往不是好查询。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多模态嵌入是可缓存的跨模态余弦空间，来自双塔对比。</li><li>与 VLM 早融合分工：检索对绑定。</li><li>评测用图文召回，不用分类榜代理一切。</li><li>出处：CLIP；SigLIP；ImageBind 式多模态锚空间。</li></ul>',6))])}const P=o(A,[["render",E]]);export{g as __pageData,P as default};
